70	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
71	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
