302	    /** Matches a well-formed postcode: exactly 4 digits. */
303	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
304	
305	    /**
306	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
307	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
308	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
309	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
310	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
311	     */
312	    private static boolean isPostcodeValidForCity(Owner owner) {
313	        String postcode = owner.getPostcode();
314	        if (postcode == null) {
315	            return true;
316	        }
317	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
318	            return false;
319	        }
320	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
321	        if (range == null) {
322	            return true;
323	        }
324	        int value = Integer.parseInt(postcode);
325	        return value >= range[0] && value <= range[1];
326	    }
327	
328	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
329	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
330	
331	    /**
332	     * Required national-number length per country code: '+61' (Australia) expects 9 national
333	     * digits and '+1' (NANP) expects 10. A number whose country code is listed here but whose
334	     * national part is not the required length is rejected.
335	     */
336	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
337	        "+61", 9, "+1", 10);
338	
339	    /**
340	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
341	     * code are kept when present; otherwise country code '+61' is assumed and a single
342	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
343	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
344	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
345	     * Returns {@code null} when the number cannot form a valid E.164 value.
346	     */
347	    private static String normalizeTelephone(String telephone) {
348	        if (telephone == null) {
349	            return null;
350	        }
351	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
352	        String e164;
353	        if (cleaned.startsWith("+")) {
354	            e164 = cleaned;
355	        } else {
356	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
357	            e164 = "+61" + national;
358	        }
359	        if (!E164_PATTERN.matcher(e164).matches()) {
360	            return null;
361	        }
362	        return hasValidNationalNumberLength(e164) ? e164 : null;
363	    }
364	
365	    /**
366	     * Whether the national number of a well-formed E.164 value has the length required for its
367	     * country code. Country codes not listed in {@link #NATIONAL_NUMBER_LENGTHS} carry no
368	     * per-country length rule and are accepted.
369	     */
370	    private static boolean hasValidNationalNumberLength(String e164) {
371	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
372	            String countryCode = entry.getKey();
373	            if (e164.startsWith(countryCode)) {
374	                return e164.length() - countryCode.length() == entry.getValue();
375	            }
376	        }
377	        return true;
378	    }
379	
380	    /**
381	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
382	     * code, membership number, household id, namesake count and household member count. Each is
383	     * derived from the owner's already-normalized fields and the existing owner population, so this
384	     * must run before the owner is saved, while the counts still exclude the owner being created.
385	     */
386	    private void assignRegistrationAttributes(Owner owner) {
387	        owner.setCustomerCode(generateCustomerCode(owner));
388	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
389	        owner.setHouseholdId(householdId(owner));
390	        owner.setNamesakeCount(countNamesakes(owner));
391	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
392	        assignPossibleDuplicate(owner);
393	    }
394	
395	    /**
396	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
397	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's last name
398	     * (compared case-insensitively with collapsed whitespace) and postcode but carries a different
399	     * telephone. Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf}
400	     * to the matching owner's id. Runs before save, against the existing owner population.
401	     */
402	    private void assignPossibleDuplicate(Owner owner) {
403	        Integer matchId = findPossibleDuplicateOf(owner);
404	        owner.setPossibleDuplicate(matchId != null);
405	        owner.setPossibleDuplicateOf(matchId);
406	    }
407	
408	    /**
409	     * The id of an existing owner that shares {@code owner}'s postcode and last name (compared
410	     * case-insensitively with collapsed whitespace) but has a different telephone, or {@code null}
411	     * when there is none. When several match, the lowest id is returned. An owner without a postcode
412	     * never matches.
413	     */
414	    private Integer findPossibleDuplicateOf(Owner owner) {
415	        String postcode = owner.getPostcode();
416	        if (postcode == null) {
417	            return null;
418	        }
419	        String lastName = normalizeHouseholdField(owner.getLastName());
420	        String telephone = owner.getTelephone();
421	        return this.clinicService.findAllOwners().stream()
422	            .filter(existing -> existing.getId() != null
423	                && postcode.equals(existing.getPostcode())
424	                && normalizeHouseholdField(existing.getLastName()).equals(lastName)
425	                && !telephone.equals(existing.getTelephone()))
426	            .map(Owner::getId)
427	            .min(Integer::compareTo)
428	            .orElse(null);
429	    }
430	
431	    /**
432	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
433	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
434	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
435	     * owner's last name (e.g. 'NSW-1A2B3C4D'). There are no sequence numbers: the identity is a pure
436	     * function of the region and the (telephone, last name) pair.
437	     */
438	    private String generateCustomerCode(Owner owner) {
439	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
440	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
441	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
442	        return owner.getRegion() + "-" + hash8;
443	    }
444	
445	    /**
446	     * The number of existing owners registered in {@code city}, compared case-insensitively
447	     * with collapsed whitespace.
448	     */
449	    private int countOwnersInCity(String city) {
450	        String normalized = normalizeHouseholdField(city);
451	        return (int) this.clinicService.findAllOwners().stream()
452	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
453	            .count();
454	    }
455	
456	    /**
457	     * The effective registration date to store for a new owner: the date supplied on the request
458	     * when present, otherwise the current server date, in either case rolled forward to a business
459	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
460	     * This single point of resolution is what every registration-date-derived value (the stored
461	     * date, the membership number's year segment, the per-day create-limit) is computed from.
462	     */
463	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
464	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
465	        return toBusinessDay(date);
466	    }
467	
468	    /**
469	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
470	     * following Monday; a weekday is returned unchanged.
471	     */
472	    private static LocalDate toBusinessDay(LocalDate date) {
473	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
474	            date = date.plusDays(1);
475	        }
476	        return date;
477	    }
478	
479	    /**
480	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
481	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
482	     */
483	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
484	        String yy = String.format("%02d", registrationDate.getYear() % 100);
485	        return customerCode + "-M" + yy;
486	    }
487	
488	    /**
489	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
490	     * last name, compared case-insensitively.
491	     */
492	    private int countNamesakes(Owner owner) {
493	        String firstName = normalizeHouseholdField(owner.getFirstName());
494	        String lastName = normalizeHouseholdField(owner.getLastName());
495	        return (int) this.clinicService.findAllOwners().stream()
496	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
497	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
498	            .count();
499	    }
500	
501	    /**
502	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
503	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
504	     * unusually high daily signup volume.
505	     */
506	    private boolean isBulkSignupWarning() {
507	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
508	    }
509	
510	    /** The number of existing owners whose registration date is {@code date}. */
511	    private int countOwnersRegisteredOn(LocalDate date) {
512	        return (int) this.clinicService.findAllOwners().stream()
513	            .filter(existing -> date.equals(existing.getRegistrationDate()))
514	            .count();
515	    }
516	
517	    /**
518	     * The single derived key all duplicate detection flows through, formed from the owner's
519	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
520	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
521	     * id is derived, so the household segment is empty at that point. Because the telephone is part
522	     * of the key, two owners in the same household with different telephones resolve to different
523	     * keys and are both allowed.
524	     */
525	    private static String identityKey(Owner owner) {
526	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
527	        String email = owner.getEmail() == null ? "" : owner.getEmail();
528	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
529	        return telephone + "|" + email + "|" + household;
530	    }
531	
532	    /**
533	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
534	     * duplicate condition: the previously separate telephone, email and household checks are now all
535	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
536	     * trips it is rejected with {@code 409 CONFLICT}.
537	     */
538	    private boolean isDuplicate(Owner owner) {
539	        String key = owner.getIdentityKey();
540	        return this.clinicService.findAllOwners().stream()
541	            .map(Owner::getIdentityKey)
542	            .filter(existing -> existing != null)
543	            .anyMatch(key::equals);
544	    }
545	
546	    /** Common street-type abbreviations expanded during address normalization. */
547	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
548	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
549	
550	    /**
551	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
552	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
553	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
554	     * string when {@code address} is null or blank after normalization.
555	     */
556	    private static String normalizeAddress(String address) {
557	        if (address == null) {
558	            return "";
559	        }
560	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
561	        if (collapsed.isEmpty()) {
562	            return "";
563	        }
564	        StringBuilder sb = new StringBuilder(collapsed.length());
565	        for (String token : collapsed.split(" ")) {
566	            if (sb.length() > 0) {
567	                sb.append(' ');
568	            }
569	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
570	        }
571	        return sb.toString();
572	    }
573	
574	    /**
575	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
576	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
577	     */
578	    private static String normalizeHouseholdField(String value) {
579	        if (value == null) {
580	            return "";
581	        }
582	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
583	    }
584	
585	    /**
586	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
587	     * same address compared case-insensitively with collapsed whitespace.
588	     */
589	    private List<Owner> findHousemates(Owner owner) {
590	        String lastName = normalizeHouseholdField(owner.getLastName());
591	        String address = normalizeHouseholdField(owner.getAddress());
592	        return this.clinicService.findAllOwners().stream()
593	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
594	                && normalizeHouseholdField(existing.getAddress()).equals(address))
595	            .toList();
596	    }
597	
598	    /**
599	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
600	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
601	     */
602	    private int countHouseholdMembers(Owner owner) {
603	        return findHousemates(owner).size() + 1;
604	    }
605	
606	    /**
607	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
608	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
609	     * deterministically from those normalized fields so housemates always resolve to the same value,
610	     * regardless of registration order.
611	     */
612	    private static String householdId(Owner owner) {
613	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
614	            + normalizeHouseholdField(owner.getAddress());
615	        return sha256Hex(key).substring(0, 24);
616	    }
617	
618	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
619	    private static String sha256Hex(String input) {
620	        try {
621	            byte[] digest = MessageDigest.getInstance("SHA-256")
622	                .digest(input.getBytes(StandardCharsets.UTF_8));
623	            StringBuilder sb = new StringBuilder(digest.length * 2);
624	            for (byte b : digest) {
625	                sb.append(String.format("%02X", b));
626	            }
627	            return sb.toString();
628	        }
629	        catch (NoSuchAlgorithmException e) {
630	            throw new IllegalStateException("SHA-256 not available", e);
631	        }
632	    }
633	}
